/**
 * Tests for the public /verify-cael endpoint logic (verify-cael.ts), which
 * backs the verifyUrl emitted by solve_* results. Exercises the decision layer
 * end-to-end against a REAL receipt generated by handleSimulationTool, without
 * booting the HTTP server (verify-cael.ts is side-effect-free by design).
 *
 * Regression target: task_1780197628410_t4c8 — the emitted verifyUrl used to
 * 404. These tests pin that (a) a self-contained traceJSONL receipt POSTed back
 * verifies, (b) a tampered receipt is rejected, (c) an unknown traceId is a
 * 200 verifiable:false (not a 404 / not a 500), and (d) browser HTML vs JSON
 * content negotiation works.
 */

import { describe, expect, it, vi } from 'vitest';

// Same deterministic Sim mock the simulation-tools suite uses, so the receipt
// produced here replays deterministically.
vi.mock('@holoscript/engine', () => {
  class ThermalSolver {
    private steps = 0;
    constructor(private readonly config: Record<string, unknown>) {
      if (!Array.isArray(config.gridResolution)) throw new Error('gridResolution required');
      if (!Array.isArray(config.domainSize)) throw new Error('domainSize required');
      if (!config.materials || typeof config.defaultMaterial !== 'string') {
        throw new Error('material config required');
      }
    }
    step(): void {
      this.steps += 1;
    }
    getTemperatureGrid(): Record<string, unknown> {
      return {
        gridResolution: this.config.gridResolution,
        domainSize: this.config.domainSize,
        steps: this.steps,
      };
    }
    getTemperatureField(): Float32Array {
      return new Float32Array([this.steps]);
    }
  }
  class StructuralSolverTET10 {
    solve(): void {}
    getDisplacements(): number[] {
      return [];
    }
    getVonMisesStress(): number[] {
      return [];
    }
    getSafetyFactor(): number {
      return 1;
    }
  }
  return {
    Simulation: {
      ThermalSolver,
      StructuralSolverTET10,
      computeStateDigest(
        solver: {
          fieldNames?: Iterable<string>;
          getField(name: string): Float32Array | Float64Array | null;
        },
        hashMode: 'fnv1a' | 'sha256'
      ): string {
        const fields = [...(solver.fieldNames ?? [])].sort();
        const payload = fields
          .map((name) => {
            const field = solver.getField(name);
            const values = field ? Array.from(field).join(',') : '';
            return `${name}:${values}`;
          })
          .join(';');
        return `${hashMode}:${payload}`;
      },
    },
  };
});

import { handleSimulationTool } from '../simulation-tools';
import { verifyCaelResult } from '../verify-cael';

const THERMAL_CONFIG = {
  gridResolution: [3, 3, 3],
  domainSize: [1, 1, 1],
  timeStep: 0.01,
  materials: {},
  defaultMaterial: 'water',
  boundaryConditions: [],
  sources: [],
  initialTemperature: 20,
};

async function freshReceipt(): Promise<{ traceId: string; traceJSONL: string }> {
  const solve = (await handleSimulationTool('solve_thermal', {
    config: THERMAL_CONFIG,
  })) as Record<string, unknown>;
  return { traceId: String(solve.caelTraceId), traceJSONL: String(solve.traceJSONL) };
}

describe('/verify-cael endpoint logic (verifyCaelResult)', () => {
  it('POST { traceJSONL } verifies a real receipt (the canonical external-repro path)', async () => {
    const { traceJSONL } = await freshReceipt();

    const out = await verifyCaelResult({ traceId: null, traceJSONL, wantsHtml: false });

    expect(out.status).toBe(200);
    expect(out.contentType).toContain('application/json');
    const verdict = JSON.parse(out.body);
    expect(verdict.success).toBe(true);
    expect(verdict.hashChainValid).toBe(true);
    expect(verdict.replayValid).toBe(true);
  });

  it('GET ?traceId resolves a resident trace (best-effort, same process)', async () => {
    const { traceId } = await freshReceipt();

    const out = await verifyCaelResult({ traceId, traceJSONL: null, wantsHtml: false });

    expect(out.status).toBe(200);
    const verdict = JSON.parse(out.body);
    expect(verdict.success).toBe(true);
    expect(verdict.replayValid).toBe(true);
  });

  it('rejects a tampered receipt (hash chain broken)', async () => {
    const { traceJSONL } = await freshReceipt();
    const tampered = traceJSONL.replace('"event":"step"', '"event":"stap"');

    const out = await verifyCaelResult({ traceId: null, traceJSONL: tampered, wantsHtml: false });

    expect(out.status).toBe(200);
    const verdict = JSON.parse(out.body);
    expect(verdict.success).toBe(false);
    expect(verdict.hashChainValid).toBe(false);
  });

  it('unknown traceId yields 200 verifiable:false (not 404, not 500) and points at the POST path', async () => {
    const out = await verifyCaelResult({
      traceId: 'cael:does-not-exist:nohash',
      traceJSONL: null,
      wantsHtml: false,
    });

    expect(out.status).toBe(200);
    const verdict = JSON.parse(out.body);
    expect(verdict.verifiable).toBe(false);
    expect(verdict.howTo.method).toBe('POST');
    expect(verdict.howTo.url).toBe('/verify-cael');
  });

  it('returns 400 when neither traceId nor traceJSONL is provided', async () => {
    const out = await verifyCaelResult({ traceId: null, traceJSONL: null, wantsHtml: false });
    expect(out.status).toBe(400);
    expect(JSON.parse(out.body).error).toMatch(/required/);
  });

  it('content-negotiates: wantsHtml renders a human-readable VERIFIED page', async () => {
    const { traceJSONL } = await freshReceipt();

    const out = await verifyCaelResult({ traceId: null, traceJSONL, wantsHtml: true });

    expect(out.status).toBe(200);
    expect(out.contentType).toContain('text/html');
    expect(out.body).toContain('CAEL Trace Verification');
    expect(out.body).toContain('VERIFIED');
  });
});
